<script setup>
import { useOpenSong } from '../../api/openSong.js'
const openSong = useOpenSong()
import { getPmtMaps } from '../../api/pmt.js'
import pmtCard from '../../components/cards/pmtCard.vue'
import { ref, onMounted, computed } from 'vue'
import { useRemScale } from '../../utils/rem.js'

import { useRouter } from 'vue-router'

useRemScale()

const router = useRouter()
const songList = ref({})
const showType0 = ref(false)
const selectedYear = ref('2026')

// 每年比赛有自己的主题色，只用在选中年份的标签上（其余界面统一走 --dt-* 令牌）
const yearConfig = {
  2024: {
    color: '#3E3146',
    text: '#F7ED01',
    file: '/files/pmt/maps2024.json'
  },
  2025: {
    color: '#323232',
    text: '#FF8E34',
    file: '/files/pmt/maps2025.json'
  },
  2026: {
    color: '#322A61',
    text: '#FFFFFF',
    file: '/files/pmt/maps2026.json'
  }
}

const yearColor = computed(() => yearConfig[selectedYear.value].color)
const yearTextColor = computed(() => yearConfig[selectedYear.value].text)

const poolText = computed(() => showType0.value ? '决赛' : '海选')

// 选中项才带年份主题色，未选中就交给 .dt-tab 的令牌样式
const tabStyle = (year) => {
  return selectedYear.value === year
    ? { background: yearConfig[year].color, color: yearConfig[year].text }
    : {}
}

const filteredSongList = computed(() => {
  const result = {}
  for (const key in songList.value) {
    const item = songList.value[key]
    if (!showType0.value && item?.Type !== 1) continue
    result[key] = item
  }
  return result
})

const fetchSongData = async () => {
  const filePath = yearConfig[selectedYear.value].file
  const data = await getPmtMaps(filePath)
  songList.value = data
}

const changeYear = (year) => {
  selectedYear.value = year
  fetchSongData()
}

onMounted(async () => {
  await fetchSongData()
})

const goToTable = (tableName) => {
  router.push({ name: tableName })
}

const handleLink = (link) => {
  if (link.startsWith('/') || !link.includes('http')) {
    goToTable(link)
  } else {
    window.open(link, '_blank')
  }
}
</script>

<template>
  <div class="dt-page">

    <div class="dt-row control-wrapper">
      <div class="dt-tabs">
        <button
          v-for="year in ['2024', '2025', '2026']"
          :key="year"
          class="dt-tab"
          :class="{ 'dt-tab--active': selectedYear === year, 'is-year-active': selectedYear === year }"
          :style="tabStyle(year)"
          @click="changeYear(year)"
        >
          {{ year }}
        </button>
      </div>

      <div class="dt-tabs" v-if="Number(selectedYear) < 2027">
        <button
          class="dt-tab"
          :class="{ 'dt-tab--active': !showType0 }"
          @click="showType0 = false"
        >
          预选赛
        </button>
        <button
          class="dt-tab"
          :class="{ 'dt-tab--active': showType0 }"
          @click="showType0 = true"
        >
          淘汰赛 / 决赛
        </button>
      </div>
    </div>

    <div class="song-list">
      <pmt-card
        v-for="(songItem, songKey) in filteredSongList"
        :key="songKey"
        class="song-card"
        :song-data="songItem"
        :song-key="songKey" @click="openSong(songKey)"
        :main-color="yearColor"
        :text-color="yearTextColor"
      />
    </div>

    <div v-if="!Object.keys(filteredSongList).length" class="dt-empty">
      该年份 · 该赛段暂无图池数据
    </div>
  </div>
</template>

<style scoped>
.control-wrapper {
  justify-content: space-between;
  margin-bottom: var(--dt-space-5);
}

/* 选中的年份标签用年份主题色，文字颜色由内联样式的 yearConfig.text 决定 */
.is-year-active {
  font-weight: 600;
}

.song-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--dt-space-3) var(--dt-space-2);
  user-select: none;
}

@media (max-width: 900px) {
  .song-list {
    grid-template-columns: 1fr;
  }

  .control-wrapper {
    justify-content: flex-start;
  }
}
</style>
